async refresh() {
  if (this.offline) {
    this.downstreamRefresh();
  } else if (this.supportsChangeLog) {
    /* we first ensure that any remaining offline items are reconciled with the calendar server */
    await this.playbackOfflineItems();
    await this.downstreamRefresh();
  } else {
    this.downstreamRefresh();
  }
